(
      'forgot-password',
      NULL,
      '"<!DOCTYPE html><html><head><link href=\"https://fonts.googleapis.com/css?family=Roboto:300,400,500\" rel=\"stylesheet\"></head><body style=\"font-family:&#039;Roboto&#039;,Arial, Helvetica, sans-serif\"><div style=\"max-width:600px; margin:0 auto; min-width:320px;            box-shadow: 0 3px 5px -1px rgba(0,0,0,.2),0 5px 8px 0 rgba(0,0,0,.14),0 1px 14px 0 rgba(0,0,0,.12)\">    <div style=\" min-height:60px; padding:40px 20px 0px 40px; \"> <img src=\"https://static.veritone.com/logo/veritone-small-logo-v2.png\" alt=\"Veritone\" style=\"max-height:44px; width:auto\"/></div><div style=\"background-color:#ffffff; padding:40px 40px\"><div style=\"font-size:18px; line-height:24px; color:#777\"><div style=\"font-size: 26px; line-height: 60px; color:#222\">Forgot your password?</div>We heard you need a password reset. Click the button below and you''ll be redirect to a secure site from which you can set a new password.<div style=\"padding: 20px 0\"><a style=\"font-size: 13px; text-decoration: none; margin: 30px 0; padding: 10px 15px; height: 44px; line-height: 44px; border-radius: 3px; color: white; text-align: center; background-color: #53ac57; text-transform: uppercase; box-shadow: 0 2px 2px 0 rgba(0, 0, 0, 0.24), 0 0 2px 0 rgba(0, 0, 0, 0.12);\" href=\"{{resetPasswordLink}}\">Reset Password</a></div><br>If you did not request this password reset, please contact us.</div></div></div><div style=\"max-width:600px; margin:70px auto; min-width:320px; font-size:12px; color:#777; text-align:center\">© {{year}} Veritone, Inc. All Rights Reserved.  <a href=\"https://www.veritone.com/wp/terms/\" style=\"color: #0288d1; text-decoration:none\">Terms of Use</a>  <a href=\"https://www.veritone.com/wp/privacy/\" style=\"color: #0288d1; text-decoration:none\">Privacy Policy</a></div></body></html>"'::jsonb,
      'Handlebars',
      '{}'::jsonb,
      'Veritone Team',
      'Password Reset',
      NOW(),
      NOW(),
      '00000000-0000-0000-0000-000000000000'
    ),
(
      'admin-reset-password',
      NULL,
      '"<!DOCTYPE html><html><head><link href=\"https://fonts.googleapis.com/css?family=Roboto:300,400,500\" rel=\"stylesheet\"></head><body style=\"font-family:&#039;Roboto&#039;,Arial, Helvetica, sans-serif\"><div style=\"max-width:600px; margin:0 auto; min-width:320px;            box-shadow: 0 3px 5px -1px rgba(0,0,0,.2),0 5px 8px 0 rgba(0,0,0,.14),0 1px 14px 0 rgba(0,0,0,.12)\"><div style=\" min-height:60px; padding:40px 20px 0px 40px; \"> <img src=\"https://static.veritone.com/logo/veritone-small-logo-v2.png\" alt=\"Veritone\" style=\"max-height:44px; width:auto\"/></div><div style=\"background-color:#ffffff; padding:40px 40px\"><div style=\"font-size:18px; line-height:24px; color:#777\"><div style=\"font-size: 26px; line-height: 60px; color:#222\">Please Change Your Password</div>An administrator for your organization has requested that you change your account password. Please click the button below to do so.<div style=\"padding: 20px 0\"><a style=\"font-size: 13px; text-decoration: none; margin: 30px 0; padding: 10px 15px; height: 44px; line-height: 44px; border-radius: 3px; color: white; text-align: center; background-color: #53ac57; text-transform: uppercase; box-shadow: 0 2px 2px 0 rgba(0, 0, 0, 0.24), 0 0 2px 0 rgba(0, 0, 0, 0.12);\" href=\"{{resetPasswordLink}}\">Change Password</a></div>Or change your password using this link:<br><a href=\"{{resetPasswordLink}}\" style=\"color: #0288d1; text-decoration: none\">{{resetPasswordLink}}</a><br><br><br>Alternatively, the next time you log into your account you will be asked to change your password.</div></div></div><div style=\"max-width:600px; margin:70px auto; min-width:320px; font-size:12px; color:#777; text-align:center\">© {{year}} Veritone, Inc. All Rights Reserved.  <a href=\"https://www.veritone.com/wp/terms/\" style=\"color: #0288d1; text-decoration:none\">Terms of Use</a>  <a href=\"https://www.veritone.com/wp/privacy/\" style=\"color: #0288d1; text-decoration:none\">Privacy Policy</a></div></body></html>"'::jsonb,
      'Handlebars',
      '{}'::jsonb,
      'Veritone Team',
      'Password Reset',
      NOW(),
      NOW(),
      '00000000-0000-0000-0000-000000000000'
    ),
(
      'new-org-user',
      NULL,
      '"<!DOCTYPE html><html><head><link href=\"https://fonts.googleapis.com/css?family=Roboto:300,400,500\" rel=\"stylesheet\"></head><body style=\"font-family:&#039;Roboto&#039;,Arial, Helvetica, sans-serif\"><div style=\"max-width:600px; margin:0 auto; min-width:320px;            box-shadow: 0 3px 5px -1px rgba(0,0,0,.2),0 5px 8px 0 rgba(0,0,0,.14),0 1px 14px 0 rgba(0,0,0,.12)\">    <div style=\" min-height:60px; padding:40px 20px 0px 40px; \"> <img src=\"https://static.veritone.com/logo/veritone-small-logo-v2.png\" alt=\"Veritone\" style=\"max-height:44px; width:auto\"/></div><div style=\"background-color:#ffffff; padding:40px 40px\"><div style=\"font-size:18px; line-height:24px; color:#777\"><div style=\"font-size: 26px; line-height: 60px; color:#222\">Hi, {{firstName}}!</div>You''ve been invited to join {{orgName}} Organization on the Veritone aiWARE Platform!<br>Activate your account now to join your team on Veritone.  This link will expire in 15 minutes.<div style=\"padding: 20px 0\"><a style=\"font-size: 13px; text-decoration: none; margin: 30px 0; padding: 10px 15px; height: 44px; line-height: 44px; border-radius: 3px; color: white; text-align: center; background-color: #53ac57; text-transform: uppercase; box-shadow: 0 2px 2px 0 rgba(0, 0, 0, 0.24), 0 0 2px 0 rgba(0, 0, 0, 0.12);\" href=\"{{resetPasswordLink}}\">Activate My Account</a></div></div></div></div><div style=\"max-width:600px; margin:70px auto; min-width:320px; font-size:12px; color:#777; text-align:center\">© {{year}} Veritone, Inc. All Rights Reserved.     <a href=\"https://www.veritone.com/wp/terms/\" style=\"color: #0288d1\">Terms of Use</a>   <a href=\"https://www.veritone.com/wp/privacy/\" style=\"color: #0288d1\">Privacy Policy</a></div></body></html>"'::jsonb,
      'Handlebars',
      '{}'::jsonb,
      'Veritone Team',
      'You have been invited to Veritone',
      NOW(),
      NOW(),
      '00000000-0000-0000-0000-000000000000'
    ),
(
      'new-org-user-no-reset',
      NULL,
      '"<!DOCTYPE html><html><head><link href=\"https://fonts.googleapis.com/css?family=Roboto:300,400,500\" rel=\"stylesheet\"></head><body style=\"font-family:''Roboto'',Arial, Helvetica, sans-serif\"><div style=\"max-width:600px; margin:0 auto; min-width:320px;            box-shadow: 0 3px 5px -1px rgba(0,0,0,.2),0 5px 8px 0 rgba(0,0,0,.14),0 1px 14px 0 rgba(0,0,0,.12)\">    <div style=\" min-height:60px; padding:40px 20px 0px 40px; \"> <img src=\"https://static.veritone.com/assets/logo-color-small.png\" alt=\"Veritone\" style=\"max-height:44px; width:auto\"/></div><div style=\"background-color:#ffffff; padding:40px 40px\"><div style=\"font-size:18px; line-height:24px; color:#777\"><div style=\"font-size: 26px; line-height: 60px; color:#222\">Hi, {{firstName}}!</div>You''ve been added to the {{orgName}} organization on aiWARE!<br>Please contact your Administrator for your password.<div style=\"padding: 20px 0\"><a style=\"font-size: 13px; text-decoration: none; margin: 30px 0; padding: 10px 15px; height: 44px; line-height: 44px; border-radius: 3px; color: white; text-align: center; background-color: #53ac57; text-transform: uppercase; box-shadow: 0 2px 2px 0 rgba(0, 0, 0, 0.24), 0 0 2px 0 rgba(0, 0, 0, 0.12);\" href=\"{{loginLink}}\">LOGIN NOW</a></div>Or login using this link:<br><a href=\"{{loginLink}}\" style=\"color: #0288d1; text-decoration: none\">{{loginLink}}</a></div></div></div><div style=\"max-width:600px; margin:70px auto; min-width:320px; font-size:12px; color:#777; text-align:center\">&copy; {{year}} Veritone, Inc. All Rights Reserved.&nbsp; &nbsp; &nbsp;<a href=\"https://www.veritone.com/wp/terms/\" style=\"color: #0288d1\">Terms of Use</a>&nbsp; &nbsp;<a href=\"https://www.veritone.com/wp/privacy/\" style=\"color: #0288d1\">Privacy Policy</a></div></body></html>"'::jsonb,
      'Handlebars',
      '{}'::jsonb,
      'Veritone Team',
      'You have been invited to Veritone',
      NOW(),
      NOW(),
      '00000000-0000-0000-0000-000000000000'
    ),
(
      'activation',
      NULL,
      '"<!DOCTYPE html><html><head><link href=\"https://fonts.googleapis.com/css?family=Roboto:300,400,500\" rel=\"stylesheet\"></head><body style=\"font-family:''Roboto'',Arial, Helvetica, sans-serif\"><div style=\"max-width:600px; margin:0 auto; min-width:320px;            box-shadow: 0 3px 5px -1px rgba(0,0,0,.2),0 5px 8px 0 rgba(0,0,0,.14),0 1px 14px 0 rgba(0,0,0,.12)\">            <!--Header starts-->            <div style=\" min-height:60px; padding:30px 20px 0px 30px; \"> <img src=\"https://static.veritone.com/assets/logo-color-small.png\" alt=\"Veritone\" style=\"max-height:44px; width:auto\"/></div>                        <!--Header ends-->    <div style=\"background-color:#fffff; padding:40px 40px\">        <div style=\"font-size:18px; line-height:24px; color:#777\">        <div style=\"font-size: 26px; line-height: 60px; color:#222\">{{#if firstName}}Hi, {{firstName}}!{{else}}Hi there!{{/if}}        </div>        Please click the button below to complete your Veritone account registration.        <div style=\"padding: 20px 0\">        <a style=\"font-size: 15px; text-decoration: none; margin: 30px 0; padding: 10px 15px; height: 44px; line-height: 44px; border-radius: 3px; color: white; text-align: center; background-color: #0091EA; text-transform: uppercase; box-shadow: 0 2px 2px 0 rgba(0, 0, 0, 0.24), 0 0 2px 0 rgba(0, 0, 0, 0.12);\" href=\"{{confirmLink}}\">        Confirm Account        </a>        </div>        Or confirm using this link:<br>        <a href=\"{{confirmLink}}\" style=\"color: #0288d1; text-decoration: none\">{{confirmLink}}</a><br>        <br>        <br>        If you did not create an account using this address, please ignore this email.        </div>    </div></div><div style=\"max-width:600px; margin:70px auto; min-width:320px; font-size:12px; color:#777; text-align:center\">© {{year}} Veritone, Inc. All Rights Reserved.  <a href=\"https://www.veritone.com/terms/\" style=\"color: #0288d1; text-decoration:none\">Terms of Use</a>  <a href=\"https://www.veritone.com/privacy/\" style=\"color: #0288d1; text-decoration:none\">Privacy Policy</a></div></body></html>"'::jsonb,
      'Handlebars',
      '{}'::jsonb,
      'Veritone Team',
      'Confirm Your Account',
      NOW(),
      NOW(),
      '00000000-0000-0000-0000-000000000000'
    ),
(
      'signup-welcome',
      NULL,
      '"<!DOCTYPE html><html><head><link href=\"https://fonts.googleapis.com/css?family=Roboto:300,400,500\" rel=\"stylesheet\"></head><body style=\"font-family:''Roboto'',Arial, Helvetica, sans-serif\"><div style=\"max-width:600px; margin:0 auto; min-width:320px;            box-shadow: 0 3px 5px -1px rgba(0,0,0,.2),0 5px 8px 0 rgba(0,0,0,.14),0 1px 14px 0 rgba(0,0,0,.12)\">    <div style=\" min-height:60px; padding:20px 20px 0px 20px; \"> <img src=\"https://static.veritone.com/assets/logo-color-small.png\" alt=\"Veritone\" style=\"max-height:44px; width:auto\"/></div><div style=\"background-color:#275693; padding: 80px 10px; text-align: center; color: #DDF0F9;\"><div style=\"font-size: 18px;line-height: 1.3\">Hi, {{firstName}}!<p style=\"font-size: 36px; margin: 20px 0\">Welcome to Veritone</p>Your account has been activated</div></div><div style=\"background-color:#ffffff; padding:40px 40px\"><div style=\"font-size:18px; line-height:24px; color:#777\">We have developed a platform of advanced cognitive engines - including transcription, face and object recognition, geolocation, A/V fingerprinting and sentiment - which can be orchestrated together and are continuously evaluated to provide the best possible outcome depending on client use case and preference for accuracy, speed, and cost. And now you have access...<div style=\"padding: 20px 0\"><a style=\"font-size: 13px; text-decoration: none; margin: 30px 0; padding: 10px 15px; height: 44px; line-height: 44px; border-radius: 3px; color: white; text-align: center; background-color: #53ac57; text-transform: uppercase; box-shadow: 0 2px 2px 0 rgba(0, 0, 0, 0.24), 0 0 2px 0 rgba(0, 0, 0, 0.12);\" href=\"{{loginLink}}\">LOGIN TO MY Account</a></div>Or login using this link:<br><a href=\"{{loginLink}}\" style=\"color: #0288d1; text-decoration: none\">{{loginLink}}</a><br><br><br>Sincerely,<br>The Veritone Team</div></div></div><div style=\"max-width:600px; margin:0 auto; min-width:320px; font-size:12px; color:#999; text-align:center\"><div style=\"margin:50px auto; width:320px;\"><a href=\"https://www.twitter.com/veritoneinc/\" style=\"display:inline-block; margin-right:40px\"><img src=\"https://static.veritone.com/veritone-ui/twitter.png\" alt=\"twitter\"></a><a href=\"https://www.linkedin.com/company/veritone-inc-/\" style=\"display:inline-block; margin-right:40px\"><img src=\"https://static.veritone.com/veritone-ui/linkedin.png\" alt=\"linkedin\"></a><a href=\"https://www.facebook.com/Veritoneinc\" style=\"display:inline-block; margin-right:40px\"><img src=\"https://static.veritone.com/veritone-ui/facebook.png\" alt=\"facebook\"></a><a href=\"https://www.youtube.com/channel/UC8PfWDmpgY25mpz0rpRiFMw\" style=\"display:inline-block\"><img src=\"https://static.veritone.com/veritone-ui/Youtube.png\" alt=\"Youtube\"></a></div><p style=\"color: #000; margin: 1em 0\">Want to learn more? Visit our <a href=\"https://help.veritone.com/\" style=\"color: #0288d1; text-decoration:none\">Knowledge Center</a>.</p>&copy; {{year}} Veritone, Inc. All Rights Reserved.&nbsp;&nbsp;<a href=\"https://www.veritone.com/terms/\" style=\"color: #0288d1; text-decoration:none\">Terms of Use</a>&nbsp;&nbsp;<a href=\"https://www.veritone.com/privacy/\" style=\"color: #0288d1; text-decoration:none\">Privacy Policy</a></div></body></html>"'::jsonb,
      'Handlebars',
      '{}'::jsonb,
      'Veritone Team',
      'Welcome to Veritone',
      NOW(),
      NOW(),
      '00000000-0000-0000-0000-000000000000'
    ),
(
      'signup-welcome-developer',
      NULL,
      '"<!DOCTYPE html><html><head><link href=\"https://fonts.googleapis.com/css?family=Roboto:300,400,500\" rel=\"stylesheet\"></head><body style=\"font-family:''Roboto'',Arial, Helvetica, sans-serif\"><div style=\"max-width:600px; margin:0 auto; min-width:320px;            box-shadow: 0 3px 5px -1px rgba(0,0,0,.2),0 5px 8px 0 rgba(0,0,0,.14),0 1px 14px 0 rgba(0,0,0,.12)\">    <div style=\" min-height:60px; padding:20px 20px 0px 20px; \"> <img src=\"https://static.veritone.com/assets/logo-color-small.png\" alt=\"Veritone\" style=\"max-height:44px; width:auto\"/></div><div style=\"background-color:#275693; padding: 80px 10px; text-align: center; color: #DDF0F9;\"><div style=\"font-size: 18px;line-height: 1.3\">Hi, {{firstName}}!<p style=\"font-size: 36px; margin: 20px 0\">Welcome to Veritone</p>Your account has been activated</div></div><div style=\"background-color:#ffffff; padding:40px 40px\"><div style=\"font-size:18px; line-height:24px; color:#777\">Veritone enables developers to build, deploy, train, and monetize cognitive engines and custom applications. Our open ecosystem design helps you quickly and easily create world-class technology solutions that add real business value. We''re happy to have you on board!<div style=\"padding: 20px 0\"><a style=\"font-size: 13px; text-decoration: none; margin: 30px 0; padding: 10px 15px; height: 44px; line-height: 44px; border-radius: 3px; color: white; text-align: center; background-color: #53ac57; text-transform: uppercase; box-shadow: 0 2px 2px 0 rgba(0, 0, 0, 0.24), 0 0 2px 0 rgba(0, 0, 0, 0.12);\" href=\"{{loginLink}}\">LOG IN TO MY Account</a></div>Or log in using this link:<br><a href=\"{{loginLink}}\" style=\"color: #0288d1; text-decoration: none\">{{loginLink}}</a><br><br><br>Sincerely,<br>The Veritone Team</div></div></div><div style=\"max-width:600px; margin:0 auto; min-width:320px; font-size:12px; color:#999; text-align:center\"><div style=\"margin:50px auto; width:320px;\"><a href=\"https://www.twitter.com/veritoneinc/\" style=\"display:inline-block; margin-right:40px\"><img src=\"https://static.veritone.com/veritone-ui/twitter.png\" alt=\"twitter\"></a><a href=\"https://www.linkedin.com/company/veritone-inc-/\" style=\"display:inline-block; margin-right:40px\"><img src=\"https://static.veritone.com/veritone-ui/linkedin.png\" alt=\"linkedin\"></a><a href=\"https://www.facebook.com/Veritoneinc\" style=\"display:inline-block; margin-right:40px\"><img src=\"https://static.veritone.com/veritone-ui/facebook.png\" alt=\"facebook\"></a><a href=\"https://www.youtube.com/channel/UC8PfWDmpgY25mpz0rpRiFMw\" style=\"display:inline-block\"><img src=\"https://static.veritone.com/veritone-ui/Youtube.png\" alt=\"Youtube\"></a></div><p style=\"color: #000; margin: 1em 0\">Want to learn more? Visit our <a href=\"https://veritone.desk.com\" style=\"color: #0288d1; text-decoration:none\">Knowledge Center</a>.</p>&copy; {{year}} Veritone, Inc. All Rights Reserved.&nbsp;&nbsp;<a href=\"https://www.veritone.com/wp/terms/\" style=\"color: #0288d1; text-decoration:none\">Terms of Use</a>&nbsp;&nbsp;<a href=\"https://www.veritone.com/wp/privacy/\" style=\"color: #0288d1; text-decoration:none\">Privacy Policy</a></div></body></html>"'::jsonb,
      'Handlebars',
      '{}'::jsonb,
      'Veritone Team',
      'Welcome to Veritone',
      NOW(),
      NOW(),
      '00000000-0000-0000-0000-000000000000'
    ),
(
      'org-registration-email-verification-1',
      NULL,
      '"<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\"><html xmlns=\"http://www.w3.org/1999/xhtml\"><head>  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\">  <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">  <title></title>  <link rel=\"stylesheet\" type=\"text/css\" href=\"https://fonts.googleapis.com/css?family=Nunito&display=swap\"></head><body style=\"width:600px; font-family:Nunito !important; padding:40px 35px\">  <div style=\" min-height:60px; padding:40px 20px 20px 0px; \"> <img src=\"https://static.veritone.com/logo/veritone-small-logo-v2.png\" alt=\"Veritone\" style=\"max-height:44px; width:auto\"/></div>  <div style=\"padding:10px 30px 30px 30px; border:1px solid #D5DFE9; border-radius:4px;\">    <div style=\"margin-top:20px\">      <p style=\"font-size:16px; color:#2A323C\">To complete your registration, please verify your email address by clicking the button below:</p>    </div>    <div style=\"margin-top:30px; margin-bottom:30px\"><a href=\"{{redirect_url}}\" style=\" background-color:#1871E8; color:#FFFFFF; border-radius:4px; margin-top:40px; padding:8px 15px; border:none; cursor:pointer; text-decoration:none\">Verify Email Address</a></div>          <p style=\"font-size:16px; color:#2A323C\">If you didn’t create an account using this address, please disregard this email.</p>  </div>  <div style=\"text-align:center; margin-top:30px;\"><span style=\"margin-right:5px; color:#5C6269\">© {{year}} Veritone,      Inc</span><span style=\"color:#5C6269\">575 Anton blvd. Costa Mesa CA 92626</span></div>  <div style=\"margin-top:8px; text-align:center;\"><span style=\"margin-right:14px;\"><a style=\"color:#6098D1\" href=\"#{{url_privacy_policy}}\">Privacy Policy</a></span><span style=\"color:#6098D1; margin-right:14px;\"></span><span><a style=\"color:#6098D1\" href=\"#{{url_term_service}}\">Term        of Service</a></span></div></body></html>"'::jsonb,
      'Handlebars',
      '{}'::jsonb,
      'Veritone Team',
      'Verify Your Account',
      NOW(),
      NOW(),
      '00000000-0000-0000-0000-000000000000'
    ),
(
      'dev-mention-notification',
      NULL,
      '"<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\"        \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\"><html xmlns=\"http://www.w3.org/1999/xhtml\"><head>    <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\"/>    <title>Untitled Document</title>    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1\">    <style type=\"text/css\">        @media (max-width: 501px) {            .c-content {                border: 0!important;            }            .c-mention-image img {                width: 40px!important;                height: 40px!important;            }            .c-mention-button a {                padding: 7px 15px!important;            }        }    </style></head><body style=\"margin: 0; padding: 0; background: #F5F7F7;\"><div class=\"c-wrap\" style=\"            margin: 0 auto;            font-family:Roboto, Helvetica Neue, sans-serif;            font-size: 14px;            max-width: 502px;\">    <div class=\"c-logo\" style=\"padding: 20px;\">        <img src=\"https://www.veritone.com/wp-content/uploads/2017/09/Color-w-Font-Sm-1.png\" alt=\"Veritone\" height=\"44\"/>    </div>    <div style=\"background: #37B4EA;    padding: 30px 20px;    color: #fff;    font-size: 20px;\" class=\"c-header\">New Alert    </div>    <div class=\"c-content\" style=\"background-color: #fff;    padding: 20px;    border: 1px solid #ccc;    border-top: 0;       \">        <p style=\"line-height: 200%; color: #999;\">Hi {{first_name}},<br/>There was one or more new mentions that we wanted to share with you:</p>        <a href=\"{{invite_link}}\" style=\"text-decoration: none; color: #333;\">            <table cellspacing=\"0\" cellpadding=\"0\" border=\"0\" width=\"100%\" style=\"margin-top: 20px;\">                <tr>                    <td class=\"c-mention-image\" style=\"max-width: 65px;                           padding-right: 20px;\">                        {{#if program_image}}                            <img width=\"55\" height=\"55\" src=\"https://res.cloudinary.com/veritone/image/fetch/f_png,r_max,h_55,w_55/{{program_image}}\">                        {{else}}                            <img width=\"55\" height=\"55\" src=\"https://s3.amazonaws.com/static.veritone.com/logo/veritone.png\">                        {{/if}}                    </td>                    <td width=\"100%\">                        <div style=\"color: #37B4EA\">{{tracking_unit_name}}</div>                        <div style=\"color: #999; font-size: 13px; margin-top: 4px;\">{{program_name}}</div>                        <div style=\"color: #999; font-size: 12px; margin-top: 4px;\">{{media_date}}</div>                    </td>                    <td style=\"padding-left: 20px;\" class=\"c-mention-button\">                        <a href=\"{{invite_link}}\" style=\"text-decoration: none; background: #37B4EA; color: #fff; padding: 10px 30px; font-size: 12px; border-radius: 5px;\">View</a>                    </td>                </tr>            </table>        </a>        <!-- Horizontal Divider -->        <div style=\"height: 1px; background: #ccc;margin-top: 20px; margin: 20px 0 0 0;\"></div>         <!-- end mentions -->        <div class=\"c-footer\" style=\"margin-top: 20px; font-size: 12px; color: #999;\">            <div style=\"margin-top: 10px\">                Note: Mention email alerts contain a maximum of 50 mentions due to email size restrictions. Please log in to the <a style=\"color:#1D8BF1; text-decoration: none;\" href=\"https://enterprise.us-1.veritone.com/media/mentions#/mention/buy/all\">Discovery</a> application to view and verify all mentions associated with your watchlist.            </div>            {{#if creator_email}}            <div style=\"margin-top: 15px\">                You were subscribed to this alert by: {{creator_email}}            </div>            {{/if}}            {{#if unsubscribe_hash}}            <div>If you prefer not to receive this watchlist alert from Veritone, you may                <a style=\"color:#1D8BF1; text-decoration: none;\" href=\"{{unsubscribe_link}}\">unsubscribe</a>            </div>            {{/if}}            <div style=\"margin:30px 0; \">                © {{year}} Veritone, Inc.                <br> 575 Anton Blvd. Suite 100, Costa Mesa, CA 92626                <br> All rights reserved.            </div>        </div>    </div></div></body></html>"'::jsonb,
