      '"<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Strict//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd\"><html xmlns=\"http://www.w3.org/1999/xhtml\"><head>  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\">  <meta name=\"viewport\" content=\"width=device-width\">  <title>You have a new support message</title>  <link rel=\"icon\" type=\"image/x-icon\" href=\"https://www.veritone.com/wp-content/uploads/2017/05/cropped-Favicon-100x100.png\">  <style type=\"text/css\">    @media (min-width: 550px) {        .hero-image {          top: 0 !important;        }              table[class=\"body\"] {          padding-bottom: 50px !important;          padding-top: 50px !important;        }              .email-logo-masthead {          display: inline !important;          height: 35px !important;          margin-left: 0 !important;          margin-right: 0 !important;          text-align: left;        }              .email-content {          border-left: 1px solid #dadfe1 !important;          border-right: 1px solid #dadfe1 !important;        }              .email-content-block {          padding-left: 20px !important;          padding-right: 20px !important;        }      }      .email-social-bar-copy p, .email-social-bar-copy a, .email-social-bar-copy .ios-no-link {        color: white !important;        text-decoration: none !important;      }    }  </style></head><body style=\"background-color: #f6f8f8; height: 100%; margin: 0; padding: 0;\">  <div style=\"display:none;font-size:1px;color:#f6f8f8;line-height:1px;max-height:0px;max-width:0px;opacity:0;overflow:hidden;\">Just a quick note letting you know you have a new support message from Simple.</div>  <table class=\"body\" align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"background-color: #f6f8f8; height: 100%; padding-bottom: 25px; padding-left: 0; padding-right: 0; padding-top: 25px;\">    <tbody>      <tr>        <td>          <table align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">            <tbody>              <tr>                <td width=\"550\">                  <table align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\">                    <tbody>                      <tr>                        <td>                          <table class=\"\" align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\">                            <tbody>                              <tr>                            </tr></tbody>                          </table>                        </td>                      </tr>                      <tr>                        <td>                          <table class=\"email-social-bar\" align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"padding-left: 20px;padding-right: 20px;background: #3fbced;padding-bottom: 15px;padding-top: 15px;\">                            <tbody>                              <tr>                                <td class=\"email-social-bar-copy copy\" style=\"font-family: \" roboto\",=\"\" \"helvetica\",=\"\" sans-serif=\"\" !important;\"=\"\">                                  <p class=\"ios-no-link\" style=\"font-family: \" roboto\",=\"\" \"helvetica\",=\"\" sans-serif=\"\" !important;font-weight:=\"\" 300;font-size:=\"\" 1.57em;line-height:=\"\" 1.5;color:=\"\" white;\"=\"\">Expiring Watchlist</p>                                </td>                                                              </tr>                            </tbody>                          </table>                        </td>                      </tr>                      <tr>                        <td class=\"email-content\" style=\"background-color: #FFFFFF;\">                          <table class=\"\" align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\">                            <tbody>                              <tr>                                <td class=\"email-content-block copy\" style=\"font-family: \" roboto\",=\"\" \"helvetica\",=\"\" sans-serif=\"\" !important;=\"\" padding-left:=\"\" 25px;=\"\" padding-right:=\"\" padding-top:=\"\" 50px;\"=\"\">                                  <h2 style=\"margin: 0 0 0.5rem 0;line-height: 1.25;font-family: \" roboto\",=\"\" \"helvetica\",=\"\" sans-serif=\"\" !important;color:=\"\" #3e474c;font-size:=\"\" 1rem;font-weight:=\"\" 300;font-style:=\"\" normal;\"=\"\">Hi {{FirstName}},</h2>                                  <p style=\"margin-bottom: 15px; font-family: \" roboto\",=\"\" \"helvetica\",=\"\" sans-serif=\"\" !important;=\"\" font-weight:=\"\" 300;=\"\" font-size:=\"\" 16px;=\"\" line-height:=\"\" 1.5;=\"\" color:=\"\" #3e474c;\"=\"\">We wanted to let you know that your watchlist <a href=\"{{invite_link}}\" style=\"color: #3fbced;text-decoration: none;\">{{tracking_unit_name}}</a> is approaching it''s end date in <b>72 hours</b>.</p>                                  <p style=\"margin-bottom: 15px; font-family: \" roboto\",=\"\" \"helvetica\",=\"\" sans-serif=\"\" !important;=\"\" font-weight:=\"\" 300;=\"\" font-size:=\"\" 16px;=\"\" line-height:=\"\" 1.5;=\"\" color:=\"\" #3e474c;\"=\"\">Take action by logging in and extending the end date of your watchlist if you still have a need for it!</p>                                  <center style=\"font-family: \" roboto\",=\"\" \"helvetica\",=\"\" sans-serif=\"\" !important;\"=\"\">                                    <div class=\"section\" style=\"font-family: \" roboto\",=\"\" \"helvetica\",=\"\" sans-serif=\"\" !important;=\"\" padding:=\"\" 50px=\"\" 0;\"=\"\">                                      <a class=\"button\" href=\"https://www.veritone.com/login/#/\" target=\"_blank\" style=\"-moz-transition: color 0.175s cubic-bezier(0.215, 0.61, 0.355, 1); -o-transition: color 0.175s cubic-bezier(0.215, 0.61, 0.355, 1); -webkit-transition: color 0.175s cubic-bezier(0.215, 0.61, 0.355, 1); transition: color 0.175s cubic-bezier(0.215, 0.61, 0.355, 1); color: white; font-family: \" roboto\",=\"\" \"helvetica\",=\"\" sans-serif=\"\" !important;=\"\" background-color:=\"\" #3fbced;=\"\" border-radius:=\"\" 3px;=\"\" padding:=\"\" 15px=\"\" 17px;=\"\" text-decoration:=\"\" none;\"=\"\">Login</a>                                    </div>                                  </center>                                  {{#if unsubscribe_hash}}                                  <p class=\"signout light-type\" style=\"margin-bottom: 15px; font-family: \" roboto\",=\"\" \"helvetica\",=\"\" sans-serif=\"\" !important;=\"\" font-weight:=\"\" 300;=\"\" font-size:=\"\" 12px;=\"\" line-height:=\"\" 1.5;=\"\" color:=\"\" #788991;\"=\"\">You were enrolled in this service at the time of watchlist creation and are notified due to it''s upcoming expiration </p>                                  {{/if}}                                  <div class=\"padding-break\" style=\"font-family: \" roboto\",=\"\" \"helvetica\",=\"\" sans-serif=\"\" !important;=\"\" margin-top:=\"\" 50px;\"=\"\"></div>                                </td>                              </tr>                            </tbody>                          </table>                        </td>                      </tr>                      <tr>                        <td class=\"email-content-border\" style=\"border-top: 1px solid #dadfe1;\"></td>                      </tr>                    </tbody>                  </table>                  <table class=\"\" align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\">                    <tbody>                      <tr>                        <td align=\"center\" class=\"email-disclaimer copy\" style=\"font-family: \" roboto\",=\"\" \"helvetica\",=\"\" sans-serif=\"\" !important;=\"\" padding-left:=\"\" 50px;=\"\" padding-right:=\"\" padding-top:=\"\" 15px;=\"\" padding-bottom:=\"\" 15px;\"=\"\">                          <p style=\"margin-bottom: 15px; font-family: \" roboto\",=\"\" \"helvetica\",=\"\" sans-serif=\"\" !important;=\"\" font-weight:=\"\" 400;=\"\" font-size:=\"\" 11px;=\"\" line-height:=\"\" 1.5;=\"\" color:=\"\" #788991;=\"\" margin-top:=\"\" 0;\"=\"\">© {{year}} {{via}} All Rights Reserved.                <br> 2420 17th St. 3rd Floor, Denver, CO 80202 </p>                        </td>                      </tr>                    </tbody>                  </table>                </td>              </tr>            </tbody>          </table>        </td>      </tr>    </tbody>  </table></body></html>"'::jsonb,
