      '"<html xmlns=\"http://www.w3.org/1999/xhtml\">  <head>    <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\"/>    <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\"/>    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"/>    <title></title>    <link rel=\"stylesheet\" type=\"text/css\" href=\"https://fonts.googleapis.com/css?family=Nunito&display=swap\"/>  </head>  <body>    <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"border-collapse:collapse; padding:0; margin:0px;\">      <tr valign=\"top\">        <td align=\"center\">          <div style=\"width:600px; font-family:Nunito !important; padding:40px 0px; text-align:start;\">            <div style=\"text-align:center; margin-bottom:30px;\">              <img src=\"https://static.veritone.com/logo/veritone-small-logo-v2.png\" width=\"250px\"/>            </div>            <div style=\"padding:10px 30px 40px 30px; border:1px solid #D5DFE9; border-radius:4px;\">              <div style=\"display:flex; margin-bottom:30px; margin-top:30px;\">                {{#if organization_icon}}                  <img width=\"40\" height=\"40\" style=\"margin-right:25px; border-radius:50%;\" src=\"{{organization_icon}}\"/>                {{/if}}                <div>                  <div style=\"font-weight:400; font-size:14px; color:#5C6269\">Veritone is inviting you to join the</div>                  <div style=\"font-weight:400; font-size:18px; color:#2A323C\">{{organization_name}} organization</div>                </div>              </div>              <hr style=\"border:0.25px solid #d5dfe9;\"/>              <div style=\"display:flex; margin-bottom:30px; margin-top:30px;\">                {{#if requestor_avatar}}                  <img width=\"40\" height=\"40\" style=\"margin-right:25px; border-radius:50%;\" src=\"{{requestor_avatar}}\"/>                {{else}}                  <div style=\"background-color:#1565C0; color:#FFFFFF;font-size:16px; padding:10px 13px; border-radius:50%; margin-right:25px\">{{requestor_shortname}}</div>                {{/if}}                <div>                  <div style=\"font-size:16px; color:#2A323C;\">                    <span style=\"font-weight:600;\">{{requestor_name}} </span>has requested you to join the <span style=\"font-weight:600;\">{{organization_name}} organization</span>                  </div>                </div>              </div>              {{#if optional_message}}                <div style=\"background-color:#EEF3F9; margin-bottom:41px; padding:20px;\">                  <div style=\"font-weight:600; font-size:14px; color:#5C6269; margin-bottom:8px;\">Message</div>                  <div style=\"color:#2A323C; font-size:16px;\">{{optional_message}}</div>                </div>              {{/if}}              <hr style=\"border:0.25px solid #d5dfe9;\"/>              <div style=\"margin-top:20px\">                <p style=\"font-size:16px; color:#2A323C\">To get started, select Accept invitation. If you already have an aiWARE user account, you can then link to your existing aiWARE account.</p>                  <p style=\"font-size:16px; color:#2A323C\">This invitation will be expired in <span style=\"font-weight:600;\">{{expiration_date}}</span>. If you have any questions, contact <a style=\"text-decoration:none;\" href=\"{{url_to_support}}\">support@veritone.com</a>                </p>              </div>              <div>                <a href=\"{{url_acceptable_invitation}}\" style=\"background-color:#1871E8; color:#FFFFFF; border-radius:4px; margin-top:30px; padding:8px 15px; border:none; cursor:pointer;text-decoration:none;\">Accept invitation</a>              </div>            </div>            <div style=\"text-align:center; margin-top:30px;\">              <span style=\"color:#5C6269\">© {{year}} Veritone, inc</span>            </div>            <div style=\"margin-top:8px; text-align:center;\">              <span style=\"margin-right:14px;\">                <a style=\"color:#6098D1;text-decoration:none;\" href=\"{{url_privacy_policy}}\">Privacy Policy</a>              </span>              <span style=\"color:#C4C4C4; margin-right:14px;\">.</span>              <span>                <a style=\"color:#6098D1;text-decoration:none;\" href=\"{{url_term_service}}\">Term of Service</a>              </span>            </div>          </div>        </td>      </tr>    </table>  </body></html>"'::jsonb,
